    61	const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
    62	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
    63	  clients.push(client);
    64	  const frames: Frame[] = [];
    65	  let connected: Frame = {type: ''};
    66	  await new Promise<void>(resolve => {
    67	    client.on('message', raw => {
    68	      const frame = JSON.parse(String(raw)) as Frame;
    69	      if (frame.type !== 'connected') {
    70	        if (frame.type === 'pong') {
    71	          resolve();
    72	          return;
    73	        }
    74	        frames.push(frame);
    75	        return;
    76	      }
    77	      connected = frame;
    78	      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
    79	      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    80	    });
    81	  });
    82	  return {connected, frames};
    83	};
